class Solution:
    def longestPalindrome(self, s: str) -> str:
        if len(s) < 2:
            return s

        def expand(l: int, r: int) -> int:
            while l >= 0 and r < len(s) and s[l] == s[r]:
                l -= 1
                r += 1
            return r - l - 1

        start, best = 0, 1
        for i in range(len(s)):
            for l, r in ((i, i), (i, i + 1)):
                cur = expand(l, r)
                if cur > best:
                    best = cur
                    start = l - (cur - 1) // 2
        return s[start:start + best]

